#include <string.h>
#include <stdint.h>
#include <stdlib.h>

#include "config.h"
#include "read.h"

static unsigned int
readname_loop(char *packet, int packetlen, char **src, char *dst, size_t length, size_t loop)
{
	char *dummy;
	char *s;
	char *d;
	char *pktend;
	unsigned int len;
	unsigned int sublen;
	int offset;
	char c = 0;

	if (loop <= 0)
		return 0;

	len = 0;
	s = *src;
	pktend = packet + packetlen;
	d = dst;
	while(s < pktend && *s && len < length - 2) {
		c = *s++;
		if (s >= pktend) {
			break; /* label length byte is the last byte of the packet */
		}

		/* is this a compressed label? */
		if ((c & 0xc0) == 0xc0) {
			/* s is already incremented to the low byte here */
			if (s >= pktend) {
				/* pointer high byte present, low byte missing */
				s = pktend - 1;
				if (len == 0) {
					/* Bad jump first in name */
					return 0;
				}
				break; /* Bad jump after some data */
			}
			offset = (((s[-1] & 0x3f) << 8) | (s[0] & 0xff));
			if (offset >= packetlen) {
				if (len == 0) {
					/* Bad jump first in packet */
					return 0;
				} else {
					/* Bad jump after some data */
					break;
				}
			}
			dummy = packet + offset;
			sublen = readname_loop(packet, packetlen, &dummy, d, length - len, loop - 1);
			if (sublen == 0) {
				if (len == 0)
					return 0;
				break;
			}
			len += sublen;
			goto end;
		}

		while(c && s < pktend && len < length - 1) {
			*d++ = *s++;
			len++;

			c--;
		}

		if (len >= length - 1 || s >= pktend) {
			break; /* We used up all space or the packet */
		}

		if (*s != 0) {
			*d++ = '.';
			len++;
		}
	}
	dst[len++] = '\0';
	if (s >= pktend || *s != 0 || c != 0)
		return 0;

end:
	(*src) = s+1;
	return len;
}

unsigned int
readname(char *packet, int packetlen, char **src, char *dst, size_t length)
{
	*dst = '\0';
	return readname_loop(packet, packetlen, src, dst, length, 10);
}

unsigned int
readshort(char *packet, char **src, unsigned short *dst)
{
	unsigned char *p;
	(void)packet;

	p = (unsigned char *) *src;
	*dst = (p[0] << 8) | p[1];

	(*src) += sizeof(unsigned short);
	return sizeof(unsigned short);
}

unsigned int
readlong(char *packet, char **src, uint32_t *dst)
{
	/* A long as described in dns protocol is always 32 bits */
	unsigned char *p;
	(void)packet;

	p = (unsigned char *) *src;

	*dst = ((uint32_t)p[0] << 24)
		 | ((uint32_t)p[1] << 16)
		 | ((uint32_t)p[2] << 8)
		 | ((uint32_t)p[3]);

	(*src) += sizeof(uint32_t);
	return sizeof(uint32_t);
}

unsigned int
readdata(char *packet, char **src, char *dst, size_t len)
{
	memcpy(dst, *src, len);
	(void)packet;

	(*src) += len;

	return len;
}

unsigned int
readtxtbin(char *packet, char **src, size_t srcremain, char *dst, size_t dstremain)
{
	unsigned char *uc;
	unsigned int tocopy;
	unsigned int dstused = 0;
	(void)packet;

	while (srcremain > 0)
	{
		uc = (unsigned char*) (*src);
		tocopy = *uc;
		(*src)++;
		srcremain--;

		if (tocopy > srcremain)
			return 0;	/* illegal, better have nothing */
		if (tocopy > dstremain)
			return 0;	/* doesn't fit, better have nothing */

		memcpy(dst, *src, tocopy);
		dst += tocopy;
		(*src) += tocopy;
		srcremain -= tocopy;
		dstremain -= tocopy;
		dstused += tocopy;
	}
	return dstused;
}

int
putname(char **buf, size_t buflen, const char *host)
{
	char *word;
	unsigned int left;
	char *h;
	char *p;
	char *saveptr = NULL;

	h = strdup(host);
	left = buflen;
	p = *buf;

	word = strtok_r(h, ".", &saveptr);
	while (word) {
		size_t word_len = strlen(word);
		if (word_len > 63 || word_len > left) {
			free(h);
			return -1;
		}

		left -= (word_len + 1);
		*p++ = (char)word_len;
		memcpy(p, word, word_len);
		p += word_len;

		word = strtok_r(NULL, ".", &saveptr);
	}

	*p++ = 0;

	free(h);

	*buf = p;
	return buflen - left;
}

int
putbyte(char **dst, unsigned char value)
{
	**dst = value;
	(*dst)++;

	return sizeof(char);
}

int
putshort(char **dst, unsigned short value)
{
	unsigned char *p;

	p = (unsigned char *) *dst;

	*p++ = (value >> 8);
	*p++ = value;

	(*dst) = (char *) p;
	return sizeof(short);
}

int
putlong(char **dst, uint32_t value)
{
	/* A long as described in dns protocol is always 32 bits */
	unsigned char *p;

	p = (unsigned char *) *dst;

	*p++ = (value >> 24);
	*p++ = (value >> 16);
	*p++ = (value >> 8);
	*p++ = (value);

	(*dst) = (char *) p;
	return sizeof(uint32_t);
}

int
putdata(char **dst, const char *data, size_t len)
{
	memcpy(*dst, data, len);

	(*dst) += len;
	return len;
}

int
puttxtbin(char **buf, size_t bufremain, const char *from, size_t fromremain)
{
	unsigned char uc;
	unsigned char *ucp = &uc;
	char *cp = (char *) ucp;
	unsigned int tocopy;
	int bufused = 0;

	while (fromremain > 0)
	{
		tocopy = fromremain;
		if (tocopy > 252)
			tocopy = 252;	/* allow off-by-1s in caches etc */
		if (tocopy + 1 > bufremain)
			return -1;	/* doesn't fit, better have nothing */

		uc = tocopy;
		**buf = *cp;
		(*buf)++;
		bufremain--;
		bufused++;

		memcpy(*buf, from, tocopy);
		(*buf) += tocopy;
		from += tocopy;
		bufremain -= tocopy;
		fromremain -= tocopy;
		bufused += tocopy;
	}
	return bufused;
}

