		/* IPv6 address */
		struct sockaddr_in6 *dest = (struct sockaddr_in6 *) address;
		ipp = (char *) &dest->sin6_addr;
		CHECKLEN(16);
		putdata(&p, ipp, sizeof(dest->sin6_addr));
	}

	len = p - buf;
	return len;
}

int
dns_encode_soa(char *buf, size_t buflen, struct dns_msg *q, const char *zone, int rcode)
{
	char rnamebuf[256];
	char nsbuf[256];
	HEADER *header;
	char *soa_start;
	char *p;

	if (buflen < sizeof(HEADER))
		return 0;

	memset(buf, 0, buflen);
	header = (HEADER*)buf;

	header->id = htons(q->id);
	header->qr = 1;		// response
	header->opcode = 0;
	header->aa = 1;		// authoritative
	header->tc = 0;
	header->rd = 0;
	header->ra = 0;
	header->rcode = rcode;

	header->qdcount = htons(1);
	header->ancount = htons(0);
	header->nscount = htons(1); // We'll include SOA
	header->arcount = htons(0);

	p = buf + sizeof(HEADER);

	// Question section
	putname(&p, buflen - (p - buf), q->name);
	CHECKLEN(4);
	putshort(&p, q->type);
	putshort(&p, C_IN);

	// Authority section (SOA)
	CHECKLEN(10);
	putname(&p, buflen - (p - buf), zone); // zone name (owner of SOA)
	putshort(&p, T_SOA);
	putshort(&p, C_IN);
	putlong(&p, 60); // TTL

	soa_start = p;
	p += 2; // skip rdlength (to be filled later)

	// Primary NS and responsible mailbox
	snprintf(nsbuf, sizeof(nsbuf), "ns.%s", zone);
	putname(&p, buflen - (p - buf), nsbuf);
	snprintf(rnamebuf, sizeof(rnamebuf), "hostmaster.%s", zone);
	putname(&p, buflen - (p - buf), rnamebuf);

	// SOA fields: serial, refresh, retry, expire, minimum
	putlong(&p, 1);		// serial
	putlong(&p, 3600);	// refresh
	putlong(&p, 1800);	// retry
	putlong(&p, 604800);	// expire
	putlong(&p, 60);	// minimum

	int soalen = p - soa_start - 2;
	putshort(&soa_start, soalen); // fill in rdlength

	return p - buf;
}

#undef CHECKLEN

unsigned short
dns_get_id(char *packet, size_t packetlen)
{
	HEADER *header;
	header = (HEADER*)packet;

	if (packetlen < sizeof(HEADER))
		return 0;

	return ntohs(header->id);
}

#define CHECKLEN(x) if (packetlen < (x) + (size_t)(data-packet))  return 0

#define SRV_MX_NAMES (250)

static int
decode_question(struct dns_msg *q, qr_t qr, char *packet, size_t packetlen, char **ppos)
{
	char name[DNS_MSG_NAME_SIZE];
	HEADER *header;
	char *data;
	unsigned int namelen;
	unsigned short qdcount;
	unsigned short class;

	header = (HEADER*)packet;

	/* Reject short packets */
	if (packetlen < sizeof(HEADER))
		return 0;

	if (header->qr != qr) {
		warnx("header->qr does not match the requested qr");
		return -1;
	}

	data = packet + sizeof(HEADER);
	qdcount = ntohs(header->qdcount);

	if (qdcount != 1) {
		warnx("%d questions in dns packet, skipping", qdcount);
		return -1;
	}
	CHECKLEN(5);
	namelen = readname(packet, packetlen, &data, name, sizeof(name));
	if (!namelen)
		return -1;
	CHECKLEN(4);
	readshort(packet, &data, &q->type);
	readshort(packet, &data, &class);

	strlcpy(q->name, name, sizeof(q->name));
	q->id = ntohs(header->id);
	q->id2 = 0;
	q->rcode = header->rcode;
	q->rtype = 0;

	if (ppos)
		*ppos = data;
	return strlen(q->name);
}

int
dns_decode_query(struct dns_msg *q, char *packet, size_t packetlen)
{
	return decode_question(q, QR_QUERY, packet, packetlen, NULL);
}

int
dns_decode_answer(char *buf, size_t buflen, struct dns_msg *q,
                  char *packet, size_t packetlen)
{
	/* For repeated SRV/MX names, we support
	 * 250 records, 250*(255+header) ~= 64kB.
	 * Only exact 10-multiples are accepted, and gaps in
	 * numbering are not jumped over (->truncated).
	 * Hopefully DNS servers won't mess around too much.
	 */
	char names[SRV_MX_NAMES][DNS_MSG_NAME_SIZE];
	char name[DNS_MSG_NAME_SIZE];
	char rdata[4*1024];
	HEADER *header;
	uint16_t ancount;
	char *data;
	char *pktend;
	unsigned int a;

	if (decode_question(q, QR_ANSWER, packet, packetlen, &data) <= 0)
		return -1;

	header = (HEADER*)packet;
	pktend = packet + packetlen;
	ancount = ntohs(header->ancount);

	if (!buf || buflen < 2)
		return -2;

	if (ancount < 1) {
		/* DNS errors like NXDOMAIN have ancount=0 and
			stop here. CNAME may also have A; MX/SRV may have
			multiple results. */
		return -1;
	}

	if (q->type == T_MX || q->type == T_SRV) {
		memset(names, 0, sizeof(names));
	}

	for (a = 0; a < ancount; a++) {
		char *rdatastart;
		uint32_t ttl;
		unsigned int rv;
		uint16_t class;
		uint16_t pref;
		uint16_t rtype;
		uint16_t rlen = 0;

		if (!readname(packet, packetlen, &data, name, sizeof(name)))
			return 0;
		CHECKLEN(10);
		readshort(packet, &data, &rtype);
		readshort(packet, &data, &class);
		readlong(packet, &data, &ttl);
		readshort(packet, &data, &rlen);
		rdatastart = data;

		/* The advertised rdata length must not exceed
			the bytes actually remaining in the packet. */
		if (data + rlen > pktend)
			return 0;

		/* Skip unwanted answer types.
		 * Tunnel uses CNAME answers to A requests, so allow that. */
		if (rtype != q->type && !(q->type == T_A && rtype == T_CNAME)) {
			data += rlen;
			continue;
		}
		q->rtype = rtype;

		switch (rtype) {
		case T_NULL:
		case T_PRIVATE:
		/* Address data only, not used for tunneling */
		case T_A:
		case T_AAAA:
			/* Assume that first answer is what we wanted */
			rv = MIN(rlen, buflen);
			return readdata(packet, &data, buf, rv);
		case T_CNAME:
			/* Assume that first answer is what we wanted */
			/* For tunnels, query type A has CNAME type answer */
			rv = readname(packet, packetlen, &data,
				      buf, MIN(buflen, DNS_MSG_NAME_SIZE));
			/* Convert from bytes written to strlen */
			return rv ? (rv - 1) : rv;
		case T_TXT:
			/* Assume that first answer is what we wanted */
			rv = readtxtbin(packet, &data, rlen, rdata,
					sizeof(rdata));
			if (rv >= 1) {
				rv = MIN(rv, buflen);
				memcpy(buf, rdata, rv);
			} else {
				rv = 0;
			}
			return rv;
		case T_MX:
		case T_SRV:
			if (rlen < 3)
				return 0;
			readshort(packet, &data, &pref);
			if (rtype == T_SRV) {
				if (rlen < 7)
					return 0;
				/* skip weight, port */
				data += 4;
			}
			if (pref % 10 == 0 && pref >= 10 &&
				pref < (SRV_MX_NAMES * 10)) {
				if (!readname(packet, packetlen, &data,
					      names[pref / 10 - 1],
					      DNS_MSG_NAME_SIZE))
					return 0;
			}
			/* always trust rlen, not name encoding */
			data = rdatastart + rlen;
			CHECKLEN(0);
			break;
		default:
			return 0;
		}
	}

	if (q->type == T_MX || q->type == T_SRV) {
		/* output is like Hname10.com\0Hname20.com\0\0 */
		size_t offset = 0;
		unsigned int i = 0;
		while (i < SRV_MX_NAMES && names[i][0] != '\0') {
			size_t l;
			if (offset + 2 > buflen)
				break;
			l = MIN(strlen(names[i]), buflen - offset - 2);
			if (l <= 0)
				break;
			memcpy(buf + offset, names[i], l);
			offset += l;
			buf[offset++] = '\0';
			i++;
		}
		if (offset >= buflen)
			return 0;
		buf[offset] = '\0';
		return offset;
	}
	return 0;
}

