START_TEST(test_decode_response_compressed_mx)
{
	char packet[4096];
	char out[4096];
	unsigned int answers;

	for (answers = 1; answers < 20; answers++) {
		char *p = packet;
		struct dns_msg q;
		unsigned int i;
		int ret;

		memset(packet, 0, sizeof(packet));
		/* Response, one question, many MX answers. */
		putshort(&p, 0x1234);
		putshort(&p, 0x8000);
		putshort(&p, 1);
		putshort(&p, answers);
		putshort(&p, 0);
		putshort(&p, 0);

		/* A 253-character presentation name (255 bytes on the wire). */
		for (i = 0; i < 4; i++) {
			int label_len = (i == 3) ? 61 : 63;
			*p++ = (unsigned char)label_len;
			memset(p, 'a' + i, (size_t)label_len);
			p += label_len;
		}
		*p++ = 0;
		putshort(&p, T_MX);
		putshort(&p, C_IN);

		for (i = 0; i < answers; i++) {
			/* Owner and exchange both compress to the question at offset 12. */
			putshort(&p, 0xc00c);
			putshort(&p, T_MX);
			putshort(&p, C_IN);
			putlong(&p, 0);
			putshort(&p, 4);
			putshort(&p, 10 * (i + 1));
			putshort(&p, 0xc00c);
		}

		ret = dns_decode_answer(out, sizeof(out), &q, packet, (size_t)(p - packet));
		ck_assert_int_eq(ret, MIN(sizeof(packet) - 1, answers * 254));
		ck_assert_uint_eq(q.rtype, T_MX);
	}
}
END_TEST

