        print(f"[tun] {line}", end="", flush=True)
    stream.close()

try:
    time.sleep(1)
    while True:
        line = process.stdout.readline()
        if not line:
            break
        print(f"[tun] {line.strip()}", flush=True)
        if line.startswith('OPEN'):
            break

    if process.poll() is not None:
        print("[bench] Failed to open")
        sys.exit(1)

