	int retval;
	int raw_mode;
	int lazymode;
	int selecttimeout;
	int hostname_maxlen;
	int rtable = 0;
	struct net_addr nameservaddr;
	int nameserv_family;

	nameserv_host = NULL;
	topdomain = NULL;
	errormsg = NULL;
	username = NULL;
	run_as = NULL;
	memset(password, 0, 33);
	foreground = 0;
	newroot = NULL;
	context = NULL;
	device = NULL;
	pidfile = NULL;
	qtype = NULL;
	down_codec = NULL;

	autodetect_frag_size = 1;
	max_downstream_frag_size = 3072;
	retval = 0;
	raw_mode = 1;
	lazymode = 1;
	selecttimeout = 4;
	hostname_maxlen = 0xFF;
	nameserv_family = AF_UNSPEC;

	progname_init(argv[0]);
	network_init();
	client_init();

	while ((choice = getopt(argc, argv, "46vfhru:t:d:R:P:m:M:F:T:O:L:I:z:")) != -1) {
		switch(choice) {
		case '4':
			nameserv_family = AF_INET;
			break;
		case '6':
			nameserv_family = AF_INET6;
			break;
		case 'v':
			version();
			/* NOTREACHED */
			break;
		case 'f':
			foreground = 1;
			break;
		case 'h':
			help(stdout, true);
			/* NOTREACHED */
			break;
		case 'r':
			raw_mode = 0;
			break;
		case 'u':
			username = optarg;
			break;
		case 't':
			newroot = optarg;
			break;
		case 'd':
			device = optarg;
			break;
		case 'R':
			rtable = atoi(optarg);
			break;
		case 'P':
			strlcpy(password, optarg, sizeof(password));

			/* XXX: find better way of cleaning up ps(1) */
			memset(optarg, 0, strlen(optarg));
			break;
		case 'm':
			autodetect_frag_size = 0;
			max_downstream_frag_size = atoi(optarg);
			break;
		case 'M':
			hostname_maxlen = atoi(optarg);
			if (hostname_maxlen > 255)
				hostname_maxlen = 255;
			if (hostname_maxlen < 10)
				hostname_maxlen = 10;
			break;
		case 'z':
			context = optarg;
			break;
		case 'F':
			pidfile = optarg;
			break;
		case 'T':
			qtype = optarg;
			if (client_set_qtype(optarg))
				errx(5, "Invalid query type '%s'", optarg);
			break;
		case 'O':       /* not -D, is Debug in server */
			down_codec = optarg;
			break;
		case 'L':
			lazymode = atoi(optarg);
			if (lazymode > 1)
				lazymode = 1;
			if (lazymode < 0)
				lazymode = 0;
			if (!lazymode)
				selecttimeout = 1;
			break;
		case 'I':
			selecttimeout = atoi(optarg);
			if (selecttimeout < 1)
				selecttimeout = 1;
			break;
		default:
			usage();
			/* NOTREACHED */
		}
	}

	check_privileges(username, newroot, 0);

	argc -= optind;
	argv += optind;

	switch (argc) {
	case 1:
		nameserv_host = get_resolvconf_addr();
		topdomain = strdup(argv[0]);
		break;
	case 2:
		nameserv_host = argv[0];
		topdomain = strdup(argv[1]);
		break;
	default:
		usage();
		/* NOTREACHED */
	}

	if (down_codec && client_set_downenc(down_codec)) {
		if (qtype) {
			warnx("Invalid downstream codec %s for type %s", down_codec, qtype);
		} else {
			warnx("Invalid downstream codec %s", down_codec);
		}
		usage();
		/* NOTREACHED */
	}

	if (max_downstream_frag_size < 1 || max_downstream_frag_size > 0xffff) {
		warnx("Use a max frag size between 1 and 65535 bytes.\n");
		usage();
		/* NOTREACHED */
	}

	if (nameserv_host) {
		if (get_addr(nameserv_host, DNS_PORT, nameserv_family, 0,
			     &nameservaddr)) {
			errx(1, "Cannot lookup nameserver '%s'", nameserv_host);
		}
		client_set_nameserver(&nameservaddr);
	} else {
		warnx("No nameserver found - not connected to any network?\n");
		usage();
		/* NOTREACHED */
	}

	if (check_topdomain(topdomain, 0, &errormsg)) {
		warnx("Invalid topdomain: %s", errormsg);
		usage();
		/* NOTREACHED */
	}

	/* The topdomain plus a small fixed overhead (header + dot +
	   safety, see hostname_need in encoding.c) must fit into the
	   maximum hostname length, otherwise no tunnel payload can ever
	   be carried - and the old code underflowed (size_t) in
	   build_hostname with such a configuration. */
	if (hostname_need(topdomain) > (size_t) hostname_maxlen) {
		warnx("Topdomain too long for -M %d: needs at least %zu characters. "
			"Use a shorter topdomain or a larger -M.",
			hostname_maxlen, hostname_need(topdomain));
		usage();
		/* NOTREACHED */
	}

	client_set_selecttimeout(selecttimeout);
	client_set_lazymode(lazymode);
	client_set_topdomain(topdomain);
	client_set_hostname_maxlen(hostname_maxlen);

	if (username != NULL) {
		if ((run_as = run_as_user_lookup(username)) == NULL) {
			warnx("User %s does not exist!\n", username);
			usage();
			/* NOTREACHED */
		}
	}

	if (strlen(password) == 0) {
		if (NULL != getenv(PASSWORD_ENV_VAR))
			snprintf(password, sizeof(password), "%s", getenv(PASSWORD_ENV_VAR));
		else
			ui_read_password(password, sizeof(password));
	}

	client_set_password(password);

	if ((tun_fd = open_tun(device)) == INVALID_SOCK) {
		retval = 1;
		goto cleanup1;
	}
	if ((dns_fd = open_udp_from_host(NULL, 0, nameservaddr.addr.ss_family, AI_PASSIVE)) == INVALID_SOCK) {
		retval = 1;
		goto cleanup2;
	}
	if (rtable > 0)
		sock_setrtable(dns_fd, rtable);

	signal(SIGINT, sighandler);
	signal(SIGTERM, sighandler);

	ui_log("Sending DNS queries for %s to %s\n",
		topdomain, format_addr(&nameservaddr));

	if (client_handshake(dns_fd, raw_mode, autodetect_frag_size, max_downstream_frag_size)) {
		retval = 1;
		goto cleanup2;
	}

	if (client_get_conn() == CONN_RAW_UDP) {
		ui_log("Sending raw traffic directly to %s\n", client_get_raw_addr());
	}

	/* Drop any tun packets received so far (MDNS etc) during possibly slow handshake. */
	tun_flush_rx(tun_fd);

	ui_log("Connection setup complete, transmitting data.\n");
	ui_log("Connection setup complete, transmitting data.\n");

	if (foreground == 0)
		do_detach();

	if (pidfile != NULL)
		do_pidfile(pidfile);

	if (newroot != NULL)
		do_chroot(newroot);

	if (run_as != NULL) {
		if (run_as_user_switch(run_as)) {
			warnx("Could not switch to user %s!\n", username);
			usage();
			/* NOTREACHED */
		}
	}

	if (context != NULL)
		do_setcon(context);

	client_tunnel(tun_fd, dns_fd);

cleanup2:
	close_udp(dns_fd);
	close_tun(tun_fd);
cleanup1:

	return retval;
}

