		ui_debug(1, "OUT  from qmem for %s == duplicate, sending illegal reply\n",
			 q->name);

		write_dns(dns_fd, q, "x", 1, &base32_ops);

		q->id = 0;	/* this query was used */
		return 1;
	}

	/* here only when no match found */
	return 0;
