static void
handle_upstream_codec_switch_request(sock_t dns_fd, char *in, int domain_len, struct dns_msg *q)
{
	unsigned int userid;
	int codec;
	const struct encoder *enc;

	if (domain_len < 3) { /* len at least 3, example: "S15" */
		write_dns(dns_fd, q, "BADLEN", 6, &base32_ops);
		return;
	}

	userid = b32_8to5(in[1]);
	if (check_authenticated_user_and_ip_and_options(userid, check_ip, &q->address) != 0) {
		write_dns(dns_fd, q, "BADIP", 5, &base32_ops);
		return; /* illegal id */
	}

	codec = b32_8to5(in[2]);
	switch (codec) {
	case 5: /* 5 bits per byte = base32 */
		enc = &base32_ops;
		break;
	case 6: /* 6 bits per byte = base64 */
		enc = &base64_ops;
		break;
	case 26: /* "2nd" 6 bits per byte = base64u, with underscore */
		enc = &base64u_ops;
		break;
	case 7: /* 7 bits per byte = base128 */
		enc = &base128_ops;
		break;
	default:
		write_dns(dns_fd, q, "BADCODEC", 8, users[userid].down_encoder);
		return;
	}
	user_switch_up_codec(userid, enc);
	write_dns(dns_fd, q, enc->name, strlen(enc->name), users[userid].down_encoder);
}

