static void
handle_version_request(sock_t dns_fd, char *in, int domain_len, struct dns_msg *q)
{
	char unpacked[64*1024];
	int read;
	uint32_t version = 0;
	unsigned int userid;
	int i;

	read = unpack_data(unpacked, sizeof(unpacked), &(in[1]), domain_len - 1, &base32_ops);
	/* Version greeting, compare and send ack/nak */
	if (read > 4) {
		/* Received V + 32bits version */
		char *reader = unpacked;
		readlong(unpacked, &reader, &version);
	}

	if (version != PROTOCOL_VERSION) {
		send_version_response(dns_fd, VERSION_NACK, PROTOCOL_VERSION, 0, q);
		syslog(LOG_INFO, "dropped user from %s, sent bad version %08X",
			format_addr(&q->address.remote), version);
		return;
	}

	if (find_available_user(&userid) == 0) {
		/* No space for another user */
		send_version_response(dns_fd, VERSION_FULL, created_users, 0, q);
		syslog(LOG_INFO, "dropped user from %s, server full",
			format_addr(&q->address.remote));
		return;
	}

	secure_random(&users[userid].seed, sizeof(users[userid].seed));
	/* Store remote IP number */
	users[userid].host = q->address.remote;

	memcpy(&(users[userid].q), q, sizeof(struct dns_msg));
	users[userid].up_encoder = &base32_ops;
	users[userid].down_encoder = &base32_ops;
	send_version_response(dns_fd, VERSION_ACK, users[userid].seed, userid, q);
	syslog(LOG_INFO, "accepted version for user #%d from %s",
