int
reliable_ctl_encode(char *dst, uint16_t bitmap)
{
	dst[0] = RELIABLE_CTRL_MARKER;
	dst[1] = rel_b32[bitmap & 0x0f];
	dst[2] = rel_b32[(bitmap >> 4) & 0x0f];
	dst[3] = rel_b32[(bitmap >> 8) & 0x0f];
	dst[4] = rel_b32[(bitmap >> 12) & 0x0f];
	return RELIABLE_CTRL_LEN;
