reliable_ctl_decode(const char *src, size_t srclen, uint16_t *bitmap)
{
	unsigned int i;
	unsigned int value = 0;

	if (!src || !bitmap || srclen < RELIABLE_CTRL_LEN ||
	    src[0] != RELIABLE_CTRL_MARKER)
		return 0;

	for (i = 1; i < RELIABLE_CTRL_LEN; i++) {
		char c = src[i];
		const char *p;
		unsigned int nibble;

		if (!c)
			return 0;
		if (c >= 'A' && c <= 'Z')
			c = (char) (c | 0x20);
		p = strchr(rel_b32, c);
		if (!p)
