static int
tunnel_tun(sock_t tun_fd, struct dnsfd *dns_fds)
{
	unsigned long outlen;
	struct ip *header;
	char out[64*1024];
	char in[64*1024];
	int userid;
	int read;

	if ((read = read_tun(tun_fd, in, sizeof(in))) <= 0)
		return 0;

	/* find target ip in packet, in is padded with 4 bytes TUN header */
	header = (struct ip*) (in + 4);
	userid = find_user_by_ip(header->ip_dst);
	if (userid < 0)
		return 0;

	outlen = sizeof(out);
	compress2((uint8_t*)out, &outlen, (uint8_t*)in, read, 9);

	if (users[userid].conn == CONN_DNS_NULL) {
#ifdef OUTPACKETQ_LEN
		/* If a packet is being sent, try storing the new one in the queue.
		   If the queue is full, drop the packet. TCP will hopefully notice
		   and reduce the packet rate. */
		if (users[userid].outpacket.len > 0) {
			save_to_outpacketq(userid, out, outlen);
			return 0;
		}
#endif

		start_new_outpacket(userid, out, outlen);

		/* Start sending immediately if query is waiting */
		if (users[userid].q_sendrealsoon.id != 0) {
			send_chunk_or_dataless(dns_fds, userid, &users[userid].q_sendrealsoon);
		} else if (users[userid].q.id != 0) {
			send_chunk_or_dataless(dns_fds, userid, &users[userid].q);
		}

		return outlen;
	} else { /* CONN_RAW_UDP */
		sock_t dns_fd = get_dns_fd(dns_fds, &users[userid].raw_addr);
		send_raw(dns_fd, out, outlen, userid, RAW_HDR_CMD_DATA, &users[userid].raw_addr);
		return outlen;
	}

